/* ═══ UI extras, hand-added on top of the build above (1 November 2026) ═══════════════════════
   This file's game code is a compiled bundle; nothing here reaches into it. The one thing added
   is the fullscreen switch: a button in the menu's corner next to the Facebook and YouTube ones,
   and the F key anywhere, including mid-run. Where the browser has no Fullscreen API (iPhone
   Safari), the button is never added and F does nothing — the game is untouched either way. */
(function () {
  "use strict";
  var root = document.documentElement,
    doc = document;
  var request = root.requestFullscreen || root.webkitRequestFullscreen;
  var exit = doc.exitFullscreen || doc.webkitExitFullscreen;
  if (!request || !exit) return;

  var btn = null,
    word = null;

  function onAir() {
    return !!(doc.fullscreenElement || doc.webkitFullscreenElement);
  }

  function paint() {
    if (!btn) return;
    var on = onAir();
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    btn.setAttribute(
      "aria-label",
      on ? "ফুলস্ক্রিন থেকে বেরোন (F)" : "ফুলস্ক্রিনে চালান (F)",
    );
    btn.title = btn.getAttribute("aria-label");
    if (word) word.textContent = on ? "ছোট করুন" : "ফুলস্ক্রিন";
  }

  function toggle() {
    try {
      if (onAir()) {
        exit.call(doc);
      } else {
        var going = request.call(root, { navigationUI: "hide" });
        if (going && typeof going.catch === "function")
          going.catch(function () {
            /* a refused switch changes nothing */
          });
      }
    } catch (error) {
      /* an older browser that wants no options: try it plainly, once */
      try {
        onAir() ? exit.call(doc) : request.call(root);
      } catch (ignored) {}
    }
  }

  function build() {
    if (btn) return;
    var corner = doc.querySelector("#menu .menu-corner");
    if (!corner) return;
    btn = doc.createElement("button");
    btn.type = "button";
    btn.id = "uiFullscreen";
    btn.className = "menu-fs";
    btn.setAttribute("aria-pressed", "false");
    btn.setAttribute("aria-keyshortcuts", "F");
    btn.innerHTML =
      '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9.5V4h5.5M20 14.5V20h-5.5M14.5 4H20v5.5M9.5 20H4v-5.5" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg><span>ফুলস্ক্রিন</span>';
    word = btn.querySelector("span");
    btn.addEventListener("click", toggle);
    corner.appendChild(btn);
    paint();
  }

  doc.addEventListener("fullscreenchange", paint);
  doc.addEventListener("webkitfullscreenchange", paint);
  doc.addEventListener("keydown", function (event) {
    if (event.code !== "KeyF" || event.ctrlKey || event.metaKey || event.altKey)
      return;
    var field = event.target;
    if (
      field &&
      (field.tagName === "INPUT" ||
        field.tagName === "TEXTAREA" ||
        field.isContentEditable)
    )
      return;
    event.preventDefault();
    toggle();
  });
  if (doc.readyState === "loading")
    doc.addEventListener("DOMContentLoaded", build);
  else build();
})();

